import React, { Component } from 'react';
import { CButton, CCard, CCardBody, CCol, CContainer, CInput, CRow, CSwitch } from '@coreui/react';
import { requestHeaderGETWithAuth, requestHeaderPOSTWithAuth, requestHeaderPUTWithAuth, requestHeaderDELETEWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import { BACKEND_NEXUS_APP_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';
import StatusModal from '../Modals/StatusModal';
import FailureModal from '../Modals/FailureModal';
import Select from 'react-select';

const FILE_NAME = "TimeLogs.js";

function getTodayDate() {
    const d = new Date();
    const yyyy = d.getFullYear();
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const dd = String(d.getDate()).padStart(2, '0');
    return `${yyyy}-${mm}-${dd}`;
}

function getAdjacentDate(dateStr, offset) {
    const d = new Date(dateStr + 'T00:00:00');
    d.setDate(d.getDate() + offset);
    const yyyy = d.getFullYear();
    const mm = String(d.getMonth() + 1).padStart(2, '0');
    const dd = String(d.getDate()).padStart(2, '0');
    return `${yyyy}-${mm}-${dd}`;
}

function formatMilitaryTime(t) {
    if (!t || t.length !== 4) return t;
    return t.substring(0, 2) + ':' + t.substring(2);
}

function addOneMinute(startTime) {
    if (!startTime || startTime.length !== 4) return startTime;
    const totalMinutes = parseInt(startTime.substring(0, 2)) * 60 + parseInt(startTime.substring(2)) + 1;
    const wrapped = totalMinutes % (24 * 60); // wrap past midnight
    const hh = String(Math.floor(wrapped / 60)).padStart(2, '0');
    const mm = String(wrapped % 60).padStart(2, '0');
    return hh + mm;
}

function computeDuration(startTime, endTime) {
    if (!startTime || !endTime || startTime.length !== 4 || endTime.length !== 4) return '—';
    const startMinutes = parseInt(startTime.substring(0, 2)) * 60 + parseInt(startTime.substring(2));
    const endMinutes = parseInt(endTime.substring(0, 2)) * 60 + parseInt(endTime.substring(2));
    let diff = endMinutes - startMinutes;
    if (diff <= 0) diff += 24 * 60; // assume next day
    const hours = Math.floor(diff / 60);
    const mins = diff % 60;
    return hours > 0 ? `${hours}h ${mins}m` : `${mins}m`;
}

function getWeekday(dateStr) {
    const days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
    const d = new Date(dateStr + 'T00:00:00');
    return days[d.getDay()];
}

class TimeLogs extends Component {

    constructor(props) {
        super(props);
        this.formRef = React.createRef();
        this.state = {
            selectedDate: getTodayDate(),
            today: getTodayDate(), // refreshed on a timer so the "not today" check survives a midnight rollover
            timeLogs: [],
            prevDayLogs: [],
            nextDayLogs: [],
            subPrograms: [],
            programs: [],
            persons: [],
            programTypeFilter: localStorage.getItem('timeLogsTypeFilter') !== null ? localStorage.getItem('timeLogsTypeFilter') : 'WORK',
            isLoaded: false,
            error: null,
            // Add/Edit form
            showForm: false,
            editingId: null,
            formTitle: '',
            formStartTime: '',
            formEndTime: '',
            formSubProgramId: '',
            formPersonId: '',
            formNotes: '',
            // Modals
            loadingModalVisible: false,
            loadingModalState: 0,
            failureModalVisible: false,
            // Notes visibility
            expandedNotes: {},
            allNotesExpanded: false,
            // View mode
            viewMode: 'list',
            // Form highlight
            formHighlight: false,
        };
    }

    componentDidMount() {
        document.title = "Time Logs";
        this.fetchReferenceData().then(() => this.fetchTimeLogs());
        window.addEventListener('beforeunload', this.handleBeforeUnload);
        // Keep re-checking the real "today" so the not-today warning stays correct even if the
        // page is left open across midnight (the selected date doesn't move, but "today" does).
        this._todayTimer = setInterval(() => {
            const today = getTodayDate();
            if (today !== this.state.today) {
                this.setState({ today });
            }
        }, 30000);
    }

    componentWillUnmount() {
        window.removeEventListener('beforeunload', this.handleBeforeUnload);
        if (this._todayTimer) {
            clearInterval(this._todayTimer);
            this._todayTimer = null;
        }
    }

    handleBeforeUnload = (e) => {
        if (this.state.showForm) {
            e.preventDefault();
            e.returnValue = '';
        }
    }

    fetchReferenceData = () => {
        const { programTypeFilter } = this.state;
        const userData = getUserDataFromLocalStorage();

        const subProgramPayload = JSON.stringify({ size: 0 });
        const programPayload = JSON.stringify({ size: 0, type: programTypeFilter || null });
        const personPayload = JSON.stringify({ size: 0 });

        return Promise.all([
            fetch(BACKEND_NEXUS_APP_BASE_URL + '/v1/sub-program/list', requestHeaderPOSTWithAuth(subProgramPayload, userData.authToken)).then(r => r.status === 200 ? r.json() : null),
            fetch(BACKEND_NEXUS_APP_BASE_URL + '/v1/program/list', requestHeaderPOSTWithAuth(programPayload, userData.authToken)).then(r => r.status === 200 ? r.json() : null),
            fetch(BACKEND_NEXUS_APP_BASE_URL + '/v1/person/list', requestHeaderPOSTWithAuth(personPayload, userData.authToken)).then(r => r.status === 200 ? r.json() : null),
        ])
        .then(([subProgramsResult, programsResult, personsResult]) => {
            const programs = (programsResult && programsResult.data) || [];
            const programIds = new Set(programs.map(p => p.id));
            const allSubPrograms = (subProgramsResult && subProgramsResult.data) || [];
            // Filter sub-programs to only those belonging to filtered programs
            const subPrograms = programTypeFilter
                ? allSubPrograms.filter(sp => programIds.has(sp.programId))
                : allSubPrograms;

            this.setState({
                subPrograms,
                programs,
                persons: (personsResult && personsResult.data) || [],
            });
        })
        .catch(error => Logger(FILE_NAME, "fetchReferenceData", "ERROR", "error", error));
    }

    refreshReferenceData = () => {
        this.fetchReferenceData();
    }

    onProgramTypeFilterChange = (e) => {
        const value = e.target.value;
        localStorage.setItem('timeLogsTypeFilter', value);
        this.setState({ programTypeFilter: value }, () => this.fetchReferenceData());
    }

    fetchTimeLogs = () => {
        const { selectedDate } = this.state;
        const userData = getUserDataFromLocalStorage();
        const prevDate = getAdjacentDate(selectedDate, -1);
        const nextDate = getAdjacentDate(selectedDate, 1);

        const API_URL_CURRENT = BACKEND_NEXUS_APP_BASE_URL + '/v1/time-log/day?date=' + selectedDate;
        const API_URL_PREV = BACKEND_NEXUS_APP_BASE_URL + '/v1/time-log/day?date=' + prevDate;
        const API_URL_NEXT = BACKEND_NEXUS_APP_BASE_URL + '/v1/time-log/day?date=' + nextDate;

        this.setState({ isLoaded: false, error: null });

        const fetchDay = (url) => fetch(url, requestHeaderGETWithAuth(userData.authToken))
            .then(response => {
                if (response.status === 200) return response.json();
                if (response.status === 401) { logoutProcedureForLocalStorage(); reloadPage(); }
                throw new Error("HTTP status is " + response.status);
            })
            .then(result => result.data || []);

        Promise.all([
            fetchDay(API_URL_PREV).catch(() => []),
            fetchDay(API_URL_CURRENT),
            fetchDay(API_URL_NEXT).catch(() => []),
        ])
        .then(([prevDayLogs, timeLogs, nextDayLogs]) => {
            Logger(FILE_NAME, "fetchTimeLogs", "SUCCESS", "timeLogs", timeLogs);
            this.setState({ isLoaded: true, timeLogs, prevDayLogs, nextDayLogs });
        })
        .catch(error => {
            Logger(FILE_NAME, "fetchTimeLogs", "ERROR", "error", error);
            this.setState({ isLoaded: true, error: error.message });
        });
    }

    onDateChange = (e) => {
        this.setState({ selectedDate: e.target.value }, () => this.fetchTimeLogs());
    }

    getFilteredTimeLogs = () => {
        const { timeLogs, programTypeFilter, subPrograms } = this.state;
        if (!programTypeFilter) return timeLogs;
        const filteredSubProgramIds = new Set(subPrograms.map(sp => sp.id));
        return timeLogs.filter(log => filteredSubProgramIds.has(log.subProgramId));
    }

    getFilteredAdjacentLogs = () => {
        const { prevDayLogs, nextDayLogs, programTypeFilter, subPrograms } = this.state;
        if (!programTypeFilter) return { prevDayLogs, nextDayLogs };
        const filteredSubProgramIds = new Set(subPrograms.map(sp => sp.id));
        return {
            prevDayLogs: prevDayLogs.filter(log => filteredSubProgramIds.has(log.subProgramId)),
            nextDayLogs: nextDayLogs.filter(log => filteredSubProgramIds.has(log.subProgramId)),
        };
    }

    /**
     * Determine overlapping logs from adjacent days.
     * Previous day: if endTime <= startTime (wraps past midnight), it overlaps into the selected day.
     * Next day: if endTime <= startTime (wraps past midnight), it means it started the selected day evening and wraps.
     * We show prev day logs that have endTime < startTime (crossing midnight) — show the portion from 00:00 to endTime.
     * We show next day logs that have endTime < startTime — show the portion from startTime to 24:00.
     * Actually the simpler heuristic: prev day entries where endTime < startTime means they span midnight.
     * The visible portion on the current day is 00:00 to endTime.
     * For next day entries where endTime < startTime, the visible portion on the current day is startTime to 24:00.
     */
    getOverlappingLogs = () => {
        const { prevDayLogs, nextDayLogs } = this.getFilteredAdjacentLogs();

        // Previous day entries that cross midnight into the selected day
        // These are entries where endTime <= startTime (e.g. start 2300, end 0100)
        const prevDayOverlapping = prevDayLogs
            .filter(log => {
                const startMin = parseInt(log.startTime.substring(0, 2)) * 60 + parseInt(log.startTime.substring(2));
                const endMin = parseInt(log.endTime.substring(0, 2)) * 60 + parseInt(log.endTime.substring(2));
                return endMin <= startMin; // crosses midnight
            })
            .map(log => ({
                ...log,
                _overlapType: 'prev',
                _visibleStartTime: '0000',
                _visibleEndTime: log.endTime,
                _label: '(prev day)',
            }));

        // Next day entries that cross midnight — they started on selected day evening
        // These are entries where endTime <= startTime
        const nextDayOverlapping = nextDayLogs
            .filter(log => {
                const startMin = parseInt(log.startTime.substring(0, 2)) * 60 + parseInt(log.startTime.substring(2));
                const endMin = parseInt(log.endTime.substring(0, 2)) * 60 + parseInt(log.endTime.substring(2));
                return endMin <= startMin; // crosses midnight
            })
            .map(log => ({
                ...log,
                _overlapType: 'next',
                _visibleStartTime: log.startTime,
                _visibleEndTime: '2359',
                _label: '(next day)',
            }));

        return { prevDayOverlapping, nextDayOverlapping };
    }

    getSubProgramName = (subProgramId) => {
        const sp = this.state.subPrograms.find(s => s.id === subProgramId);
        if (!sp) return subProgramId;
        const prog = this.state.programs.find(p => p.id === sp.programId);
        if (prog) {
            return `${sp.name} | ${prog.name} (${prog.type})`;
        }
        return sp.name;
    }

    renderSubProgramCell = (subProgramId) => {
        const sp = this.state.subPrograms.find(s => s.id === subProgramId);
        if (!sp) return subProgramId;
        const prog = this.state.programs.find(p => p.id === sp.programId);

        return (
            <span>
                <a href={'#/sub-program/' + sp.id} target="_blank" rel="noopener noreferrer" style={{ textDecoration: 'none' }}>
                    {sp.name}
                </a>
                {prog && (
                    <>
                        {' ('}
                        {prog.type}
                        {' | '}
                        <a href={'#/program/' + prog.id} target="_blank" rel="noopener noreferrer" style={{ textDecoration: 'none' }}>
                            {prog.name}
                        </a>
                        {')'}
                    </>
                )}
            </span>
        );
    }

    getSubProgramDisplay = (sp) => {
        const prog = this.state.programs.find(p => p.id === sp.programId);
        if (prog) {
            return `${prog.name} | ${sp.name} (${prog.type})`;
        }
        return sp.name;
    }

    getLogColor = (log) => {
        const workColors = [
            { bg: 'rgba(102, 126, 234, 0.12)', border: '#667eea', text: '#4c51bf' },
            { bg: 'rgba(66, 153, 225, 0.12)', border: '#4299e1', text: '#2b6cb0' },
            { bg: 'rgba(56, 178, 172, 0.12)', border: '#38b2ac', text: '#285e61' },
            { bg: 'rgba(72, 187, 120, 0.12)', border: '#48bb78', text: '#276749' },
        ];
        const personalColors = [
            { bg: 'rgba(237, 100, 166, 0.12)', border: '#ed64a6', text: '#b83280' },
            { bg: 'rgba(245, 101, 101, 0.12)', border: '#f56565', text: '#c53030' },
            { bg: 'rgba(237, 137, 6, 0.12)', border: '#ed8906', text: '#c05621' },
            { bg: 'rgba(159, 122, 234, 0.12)', border: '#9f7aea', text: '#6b46c1' },
        ];
        const sp = this.state.subPrograms.find(s => s.id === log.subProgramId);
        const prog = sp ? this.state.programs.find(p => p.id === sp.programId) : null;
        const type = prog ? prog.type : null;
        const id = log.id % 4;
        return type === 'PERSONAL' ? personalColors[id] : workColors[id];
    }

    getPersonName = (personId) => {
        if (!personId) return '—';
        const p = this.state.persons.find(per => per.id === personId);
        return p ? p.name : personId;
    }

    // Form handling
    openAddForm = () => {
        this.setState({
            showForm: true,
            editingId: null,
            formTitle: '',
            formStartTime: '',
            formEndTime: '',
            formSubProgramId: '',
            formPersonId: '',
            formNotes: '',
            formHighlight: true,
        }, () => {
            // Form renders at the top of the page; bring it into view (useful when the add
            // button that was clicked is the one at the bottom of the day's logs).
            if (this.formRef.current) {
                this.formRef.current.scrollIntoView({ behavior: 'smooth', block: 'start' });
            }
            setTimeout(() => this.setState({ formHighlight: false }), 1500);
        });
    }

    openEditForm = (log) => {
        this.setState({
            showForm: true,
            editingId: log.id,
            formTitle: log.title,
            formStartTime: log.startTime,
            formEndTime: log.endTime,
            formSubProgramId: String(log.subProgramId),
            formPersonId: log.personId ? String(log.personId) : '',
            formNotes: log.notes || '',
            formHighlight: true,
        }, () => {
            if (this.formRef.current) {
                this.formRef.current.scrollIntoView({ behavior: 'smooth', block: 'start' });
            }
            setTimeout(() => this.setState({ formHighlight: false }), 1500);
        });
    }

    closeForm = () => {
        this.setState({ showForm: false, editingId: null });
    }

    toggleNotes = (logId) => {
        this.setState(prevState => ({
            expandedNotes: { ...prevState.expandedNotes, [logId]: !prevState.expandedNotes[logId] }
        }));
    }

    toggleAllNotes = () => {
        this.setState(prevState => {
            const newExpanded = !prevState.allNotesExpanded;
            const expandedNotes = {};
            if (newExpanded) {
                // Expand all logs that have notes
                prevState.timeLogs.forEach(log => {
                    if (log.notes) expandedNotes[log.id] = true;
                });
            }
            return { allNotesExpanded: newExpanded, expandedNotes };
        });
    }

    handleFormSubmit = (e) => {
        e.preventDefault();
        const { editingId, formTitle, formStartTime, formEndTime, formSubProgramId, formPersonId, formNotes, selectedDate } = this.state;

        if (!formSubProgramId) {
            alert('Please select a Sub-Program before submitting.');
            return;
        }

        // End time is optional. When not provided, default to start time + 1 minute.
        const effectiveEndTime = formEndTime ? formEndTime : addOneMinute(formStartTime);

        const userData = getUserDataFromLocalStorage();

        this.setState({ loadingModalVisible: true, loadingModalState: 0 });

        if (editingId) {
            // Update
            const payload = { title: formTitle || null, startTime: formStartTime, endTime: effectiveEndTime, subProgramId: Number(formSubProgramId), personId: formPersonId ? Number(formPersonId) : null, notes: formNotes || null };
            const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/time-log/' + editingId;

            fetch(API_URL, requestHeaderPUTWithAuth(JSON.stringify(payload), userData.authToken))
            .then(response => {
                if (response.status === 200) return response.json();
                if (response.status === 401) { this.setState({ loadingModalVisible: false, failureModalVisible: true }); setTimeout(() => { logoutProcedureForLocalStorage(); reloadPage(); }, 500); }
                throw new Error("HTTP status is " + response.status);
            })
            .then(result => {
                Logger(FILE_NAME, "updateTimeLog", "SUCCESS", "result", result);
                this.setState({ loadingModalState: 1, showForm: false, editingId: null });
                setTimeout(() => { this.setState({ loadingModalVisible: false, loadingModalState: 0 }); this.fetchTimeLogs(); }, 800);
            })
            .catch(error => {
                Logger(FILE_NAME, "updateTimeLog", "ERROR", "error", error);
                this.setState({ loadingModalVisible: false, failureModalVisible: true });
            });
        } else {
            // Create
            const payload = { date: selectedDate, title: formTitle || null, startTime: formStartTime, endTime: effectiveEndTime, subProgramId: Number(formSubProgramId), personId: formPersonId ? Number(formPersonId) : null, notes: formNotes || null };
            const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/time-log';

            fetch(API_URL, requestHeaderPOSTWithAuth(JSON.stringify(payload), userData.authToken))
            .then(response => {
                if (response.status === 200) return response.json();
                if (response.status === 401) { this.setState({ loadingModalVisible: false, failureModalVisible: true }); setTimeout(() => { logoutProcedureForLocalStorage(); reloadPage(); }, 500); }
                throw new Error("HTTP status is " + response.status);
            })
            .then(result => {
                Logger(FILE_NAME, "createTimeLog", "SUCCESS", "result", result);
                this.setState({ loadingModalState: 1, showForm: false });
                setTimeout(() => { this.setState({ loadingModalVisible: false, loadingModalState: 0 }); this.fetchTimeLogs(); }, 800);
            })
            .catch(error => {
                Logger(FILE_NAME, "createTimeLog", "ERROR", "error", error);
                this.setState({ loadingModalVisible: false, failureModalVisible: true });
            });
        }
    }

    handleDelete = (id) => {
        if (!window.confirm('Are you sure you want to delete this time log?')) return;

        const userData = getUserDataFromLocalStorage();
        const API_URL = BACKEND_NEXUS_APP_BASE_URL + '/v1/time-log/' + id;

        this.setState({ loadingModalVisible: true, loadingModalState: 0 });

        fetch(API_URL, requestHeaderDELETEWithAuth(null, userData.authToken))
        .then(response => {
            if (response.status === 200) return response.json();
            if (response.status === 401) { this.setState({ loadingModalVisible: false, failureModalVisible: true }); setTimeout(() => { logoutProcedureForLocalStorage(); reloadPage(); }, 500); }
            throw new Error("HTTP status is " + response.status);
        })
        .then(result => {
            Logger(FILE_NAME, "deleteTimeLog", "SUCCESS", "result", result);
            this.setState({ loadingModalState: 1 });
            setTimeout(() => { this.setState({ loadingModalVisible: false, loadingModalState: 0 }); this.fetchTimeLogs(); }, 800);
        })
        .catch(error => {
            Logger(FILE_NAME, "deleteTimeLog", "ERROR", "error", error);
            this.setState({ loadingModalVisible: false, failureModalVisible: true });
        });
    }

    render() {
        const { isLoaded, error, selectedDate, timeLogs, showForm, programTypeFilter, viewMode, today } = this.state;
        const isNotToday = selectedDate !== today;

        const styles = {
            page: {
                minHeight: '100vh',
                padding: '30px 0',
            },
            header: {
                background: 'rgba(255, 255, 255, 0.95)',
                backdropFilter: 'blur(10px)',
                borderRadius: '16px',
                padding: '28px 32px',
                marginBottom: '24px',
                boxShadow: '0 10px 40px rgba(0, 0, 0, 0.1)',
                border: '1px solid rgba(255, 255, 255, 0.8)',
            },
            title: {
                fontSize: '2em',
                fontWeight: '800',
                background: 'linear-gradient(135deg, #667eea, #764ba2)',
                WebkitBackgroundClip: 'text',
                WebkitTextFillColor: 'transparent',
                margin: 0,
            },
            controls: {
                display: 'flex',
                alignItems: 'center',
                gap: '12px',
                flexWrap: 'wrap',
                marginTop: '16px',
                padding: '16px 20px',
                background: 'linear-gradient(135deg, #f8f9ff, #f0f2ff)',
                borderRadius: '12px',
                border: '1px solid #e8ecff',
            },
            weekday: {
                fontWeight: '600',
                color: '#764ba2',
                fontSize: '0.95em',
                padding: '4px 12px',
                background: 'rgba(118, 75, 162, 0.08)',
                borderRadius: '20px',
            },
            typeSelect: {
                padding: '8px 16px',
                border: '2px solid #e8ecff',
                borderRadius: '8px',
                fontWeight: '500',
                fontSize: '0.9em',
                background: 'white',
                cursor: 'pointer',
                transition: 'border-color 0.2s',
            },
            content: {
                background: 'rgba(255, 255, 255, 0.95)',
                backdropFilter: 'blur(10px)',
                borderRadius: '16px',
                padding: '28px 32px',
                boxShadow: '0 10px 40px rgba(0, 0, 0, 0.1)',
                border: '1px solid rgba(255, 255, 255, 0.8)',
            },
        };

        return (
            <div>
                {/* <CContainer> */}
                    {/* <CRow className="justify-content-center"> */}
                        {/* <CCol md="12"> */}
                            {/* Header */}
                            <div style={styles.header}>
                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '12px' }}>
                                    <h1 style={styles.title}>⏱️ Time Logs</h1>
                                    <div>
                                        {/* View toggle */}
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                                            <span style={{ fontSize: '1.2em', fontWeight: '600', color: viewMode === 'list' ? '#667eea' : '#a0aec0' }}>📋 List</span>
                                            <CSwitch
                                                color="success"
                                                shape="pill"
                                                size="lg"
                                                checked={viewMode === 'calendar'}
                                                onChange={(e) => this.setState({ viewMode: e.target.checked ? 'calendar' : 'list' })}
                                                style={viewMode === 'list' ? { backgroundColor: '#c4c9d0', borderColor: '#c4c9d0', borderRadius: '999px' } : {}}
                                            />
                                            <span style={{ fontSize: '1.2em', fontWeight: '600', color: viewMode === 'calendar' ? '#667eea' : '#a0aec0' }}>📅 Calendar</span>
                                        </div>
                                        
                                        <CButton color="primary" onClick={this.openAddForm} style={{ borderRadius: '10px', fontWeight: '600', padding: '12px 28px', fontSize: '1em', background: 'linear-gradient(135deg, #667eea, #764ba2)', border: '1rem solid' }}>➕ Add Time Log</CButton>
                                        &nbsp;
                                        <CButton color="light" onClick={this.toggleAllNotes} title={this.state.allNotesExpanded ? "Hide all notes" : "Show all notes"} style={{ borderRadius: '10px', fontWeight: '600', padding: '8px 14px', background: this.state.allNotesExpanded ? '#e8ecff' : 'white', border: '2px solid #e8ecff' }}>{this.state.allNotesExpanded ? '🙈 Hide Notes' : '👁️ Show Notes'}</CButton>
                                        &nbsp;
                                        <CButton color="light" onClick={() => { this.fetchReferenceData().then(() => this.fetchTimeLogs()); }} title="Refresh data" style={{ borderRadius: '10px', fontWeight: '600', padding: '8px 14px' }}>🔄</CButton>
                                    </div>
                                </div>

                                {/* Controls */}
                                <div style={styles.controls}>
                                    <button
                                        onClick={() => this.setState({ selectedDate: getTodayDate() }, () => this.fetchTimeLogs())}
                                        style={{ background: 'linear-gradient(135deg, #667eea, #764ba2)', color: 'white', border: 'none', borderRadius: '8px', padding: '6px 14px', cursor: 'pointer', fontWeight: '600', fontSize: '0.85em', transition: 'all 0.2s', boxShadow: '0 2px 8px rgba(102, 126, 234, 0.3)' }}
                                        title="Jump to today"
                                    >Jump 2 today</button> |
                                    <label style={{ fontWeight: '700', margin: 0, color: '#4a5568', fontSize: '0.9em' }}>📅 Date:</label>
                                    <button
                                        onClick={() => this.setState({ selectedDate: getAdjacentDate(selectedDate, -1) }, () => this.fetchTimeLogs())}
                                        style={{ background: 'white', border: '2px solid #e8ecff', borderRadius: '8px', padding: '6px 12px', cursor: 'pointer', fontWeight: '700', fontSize: '1.1em', transition: 'all 0.2s' }}
                                        title="Previous day"
                                    >◀</button>
                                    <CInput
                                        type="date"
                                        value={selectedDate}
                                        onChange={this.onDateChange}
                                        style={{ maxWidth: '180px', borderRadius: '8px', border: '2px solid #e8ecff', fontWeight: '500' }}
                                    />
                                    <button
                                        onClick={() => this.setState({ selectedDate: getAdjacentDate(selectedDate, 1) }, () => this.fetchTimeLogs())}
                                        style={{ background: 'white', border: '2px solid #e8ecff', borderRadius: '8px', padding: '6px 12px', cursor: 'pointer', fontWeight: '700', fontSize: '1.1em', transition: 'all 0.2s' }}
                                        title="Next day"
                                    >▶</button>
                                    <span style={styles.weekday}>{getWeekday(selectedDate)}</span>
                                    <select
                                        value={programTypeFilter}
                                        onChange={this.onProgramTypeFilterChange}
                                        style={styles.typeSelect}
                                    >
                                        <option value="">All Types</option>
                                        <option value="WORK">🏢 WORK</option>
                                        <option value="PERSONAL">🏠 PERSONAL</option>
                                    </select>
                                </div>
                            </div>

                            {/* Subtle "not today" warning — re-evaluated whenever `today` ticks over
                                (see the interval in componentDidMount) so it stays correct across midnight. */}
                            {isNotToday && (
                                <div style={{
                                    display: 'flex',
                                    alignItems: 'center',
                                    gap: '8px',
                                    padding: '8px 16px',
                                    marginBottom: '16px',
                                    background: 'rgba(237, 137, 54, 0.08)',
                                    border: '1px solid rgba(237, 137, 54, 0.3)',
                                    borderRadius: '10px',
                                    color: '#b7791f',
                                    fontSize: '0.9em',
                                    fontWeight: '500',
                                }}>
                                    <span>⚠️ You're viewing <strong>{selectedDate}</strong>, not today ({today}).</span>
                                    <button
                                        onClick={() => this.setState({ selectedDate: getTodayDate() }, () => this.fetchTimeLogs())}
                                        style={{ background: 'transparent', border: 'none', color: '#b7791f', fontWeight: '700', textDecoration: 'underline', cursor: 'pointer', padding: 0, fontSize: '0.9em' }}
                                        title="Jump to today"
                                    >Jump to today</button>
                                </div>
                            )}

                            {/* Form */}
                            {showForm && this.renderForm()}

                            {/* Content */}
                            <div>
                                {!isLoaded && <Loading />}
                                {isLoaded && error && (
                                    <div style={{ textAlign: 'center', padding: '40px', color: '#e53e3e', background: '#fff5f5', borderRadius: '12px', border: '1px solid #fed7d7' }}>
                                        <p style={{ fontSize: '1.1em', fontWeight: '500' }}>⚠️ Error: {error}</p>
                                    </div>
                                )}
                                {isLoaded && !error && this.renderTimeLogs(this.getFilteredTimeLogs(), viewMode, this.getOverlappingLogs())}
                            </div>

                            {/* Bottom "Add Time Log" button — convenient after scrolling through the day's logs. */}
                            {!showForm && (
                                <div style={{ display: 'flex', justifyContent: 'center', marginTop: '24px' }}>
                                    <CButton color="primary" onClick={this.openAddForm} style={{ borderRadius: '10px', fontWeight: '600', padding: '12px 28px', fontSize: '1em', background: 'linear-gradient(135deg, #667eea, #764ba2)', border: 'none' }}>➕ Add Time Log</CButton>
                                </div>
                            )}
                        {/* </CCol> */}
                    {/* </CRow> */}
                {/* </CContainer> */}
                <StatusModal visible={this.state.loadingModalVisible} loadingModalState={this.state.loadingModalState} />
                <FailureModal visible={this.state.failureModalVisible} />
            </div>
        );
    }

    renderTimeLogs(timeLogs, viewMode = 'calendar', overlappingLogs = { prevDayOverlapping: [], nextDayOverlapping: [] }) {
        const { prevDayOverlapping, nextDayOverlapping } = overlappingLogs;
        const hasOverlapping = prevDayOverlapping.length > 0 || nextDayOverlapping.length > 0;

        if (timeLogs.length === 0 && !hasOverlapping) {
            return (
                <div style={{ textAlign: 'center', padding: '60px 40px', color: '#a0aec0' }}>
                    <div style={{ fontSize: '3em', marginBottom: '12px' }}>📭</div>
                    <p style={{ fontStyle: 'italic', fontSize: '1.1em', fontWeight: '500' }}>No time logs found for this date.</p>
                    <p style={{ fontSize: '0.9em', color: '#cbd5e0' }}>Click "Add Time Log" to get started</p>
                </div>
            );
        }

        const totalMinutes = timeLogs.reduce((sum, log) => {
            const start = parseInt(log.startTime.substring(0, 2)) * 60 + parseInt(log.startTime.substring(2));
            const end = parseInt(log.endTime.substring(0, 2)) * 60 + parseInt(log.endTime.substring(2));
            let diff = end - start;
            if (diff <= 0) diff += 24 * 60;
            return sum + diff;
        }, 0);
        const totalHours = Math.floor(totalMinutes / 60);
        const totalMins = totalMinutes % 60;

        const totalTimeDisplay = `${totalHours}h ${totalMins}m`;

        if (viewMode === 'list') {
            return (
                <div>
                    <div style={{ borderRadius: '12px', border: '1px solid #e2e8f0', boxShadow: '0 2px 8px rgba(0,0,0,0.04)', overflow: 'hidden' }}>
                        <div style={{ background: 'linear-gradient(135deg, #667eea, #764ba2)', padding: '12px 20px', color: 'white', fontWeight: '700', fontSize: '0.9em', letterSpacing: '0.5px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <span>📋 LIST VIEW</span>
                            <span style={{ fontFamily: 'monospace', fontSize: '1em' }}>⏱️ {totalTimeDisplay}</span>
                        </div>
                        <div style={{ overflowX: 'auto', WebkitOverflowScrolling: 'touch' }}>
                        <table style={{ width: '100%', borderCollapse: 'collapse', minWidth: '800px' }}>
                            <thead>
                                <tr style={{ background: '#f7fafc', textAlign: 'left', borderBottom: '2px solid #e2e8f0' }}>
                                    <th style={{ padding: '12px 10px 12px 16px', color: '#4a5568', fontWeight: '700', fontSize: '0.82em', textTransform: 'uppercase', letterSpacing: '0.5px', width: '1px', whiteSpace: 'nowrap', borderRight: '1px solid #e2e8f0' }}>Time</th>
                                    <th style={{ padding: '12px 10px 12px 10px', color: '#4a5568', fontWeight: '700', fontSize: '0.82em', textTransform: 'uppercase', letterSpacing: '0.5px', maxWidth: '280px', width: '1px', borderRight: '1px solid #e2e8f0' }}>Details</th>
                                    <th style={{ padding: '12px 16px 12px 10px', color: '#4a5568', fontWeight: '700', fontSize: '0.82em', textTransform: 'uppercase', letterSpacing: '0.5px' }}>Notes</th>
                                </tr>
                            </thead>
                            <tbody>
                                {timeLogs.map((log, index) => {
                                    const color = this.getLogColor(log);
                                    return (
                                        <tr key={log.id} style={{ borderBottom: '1px solid #edf2f7', background: index % 2 === 0 ? '#ffffff' : '#f7fafc' }}>
                                            <td style={{ padding: '12px 10px 12px 16px', whiteSpace: 'nowrap', width: '1px', borderRight: '1px solid #edf2f7' }}>
                                                <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
                                                    <div style={{ display: 'flex', alignItems: 'center' }}>
                                                        <span style={{ display: 'inline-block', width: '4px', height: '14px', borderRadius: '2px', background: color.border, marginRight: '8px', verticalAlign: 'middle' }} />
                                                        <span style={{ fontFamily: 'monospace', fontWeight: '700', color: '#2d3748', fontSize: '0.92em' }}>{formatMilitaryTime(log.startTime)} – {formatMilitaryTime(log.endTime)}</span>
                                                    </div>
                                                    <span style={{ background: color.bg, padding: '3px 10px', borderRadius: '6px', fontWeight: '700', color: color.text, fontSize: '0.82em', border: '1px solid ' + color.border, width: 'fit-content' }}>{computeDuration(log.startTime, log.endTime)}</span>
                                                </div>
                                            </td>
                                            <td style={{ padding: '12px 10px 12px 10px', fontSize: '0.88em', maxWidth: '280px', width: '1px', borderRight: '1px solid #edf2f7' }}>
                                                <div style={{ display: 'flex', flexDirection: 'column', gap: '4px' }}>
                                                    <div style={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{this.renderSubProgramCell(log.subProgramId)}</div>
                                                    {log.title && <span style={{ fontWeight: '600', color: '#2d3748', fontSize: '0.92em', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{log.title}</span>}
                                                    {log.personId && <span style={{ color: '#4a5568', fontSize: '0.9em' }}>👤 {this.getPersonName(log.personId)}</span>}
                                                    {/* Actions below details */}
                                                    <div style={{ display: 'flex', gap: '6px', marginTop: '6px' }}>
                                                        <CButton color="info" size="sm" onClick={() => this.openEditForm(log)} style={{ borderRadius: '8px', padding: '4px 10px' }}>✏️</CButton>
                                                        <CButton color="danger" size="sm" onClick={() => this.handleDelete(log.id)} style={{ borderRadius: '8px', padding: '4px 10px' }}>🗑️</CButton>
                                                    </div>
                                                </div>
                                            </td>
                                            <td style={{ padding: '12px 16px 12px 10px', maxWidth: '220px' }}>
                                                {log.notes ? (
                                                    <span>
                                                        <CButton color="light" size="sm" onClick={() => this.toggleNotes(log.id)} style={{ padding: '3px 10px', fontSize: '0.75em', borderRadius: '6px', fontWeight: '600', border: '1px solid #e2e8f0' }}>
                                                            {this.state.expandedNotes[log.id] ? '🙈 Hide' : '📝 Show'}
                                                        </CButton>
                                                        {this.state.expandedNotes[log.id] && (
                                                            <div style={{ marginTop: '6px', whiteSpace: 'pre-line', fontSize: '0.82em', color: '#4a5568', background: '#f7fafc', padding: '8px 10px', borderRadius: '6px', border: '1px solid #e2e8f0' }}>{log.notes}</div>
                                                        )}
                                                    </span>
                                                ) : <span style={{ color: '#cbd5e0' }}>—</span>}
                                            </td>
                                        </tr>
                                    );
                                })}
                            </tbody>
                        </table>
                        </div>
                    </div>
                </div>
            );
        }

        // Calendar (vertical timeline) view

        // Vertical Timeline config: 12 AM (0 min) to 12 AM (1440 min)
        const TIMELINE_START = 0;
        const TIMELINE_END = 24 * 60;
        const TIMELINE_DURATION = TIMELINE_END - TIMELINE_START;
        const TIMELINE_HEIGHT = 2160; // pixels (1.5px per minute)

        const hours = [];
        for (let h = 0; h <= 24; h++) {
            hours.push(h);
        }

        return (
            <div>

                {/* Vertical Timeline */}
                <div style={{ borderRadius: '12px', border: '1px solid #e2e8f0', boxShadow: '0 2px 8px rgba(0,0,0,0.04)', overflow: 'hidden' }}>
                    {/* Header */}
                    <div style={{ background: 'linear-gradient(135deg, #667eea, #764ba2)', padding: '12px 20px', color: 'white', fontWeight: '700', fontSize: '0.9em', letterSpacing: '0.5px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                        <span>📊 DAILY TIMELINE (24 HOURS)</span>
                        <span style={{ fontFamily: 'monospace', fontSize: '1em' }}>⏱️ {totalTimeDisplay}</span>
                    </div>

                    {/* Vertical Timeline Body */}
                    <div style={{ overflowX: 'auto', WebkitOverflowScrolling: 'touch' }}>
                    <div style={{ display: 'flex', background: '#fafbff', padding: '0', minWidth: '600px' }}>
                        {/* Hour labels column */}
                        <div style={{ position: 'relative', width: '60px', height: TIMELINE_HEIGHT + 'px', flexShrink: 0, borderRight: '1px solid #e2e8f0' }}>
                            {hours.map(h => {
                                const top = ((h * 60 - TIMELINE_START) / TIMELINE_DURATION) * TIMELINE_HEIGHT;
                                const label = h === 0 ? '12 AM' : h < 12 ? h + ' AM' : h === 12 ? '12 PM' : (h - 12) + ' PM';
                                return (
                                    <div key={'hlabel-' + h} style={{ position: 'absolute', top: top + 'px', right: '8px', transform: 'translateY(-50%)', fontSize: '0.72em', color: '#a0aec0', fontWeight: '600', whiteSpace: 'nowrap' }}>
                                        {label}
                                    </div>
                                );
                            })}
                        </div>

                        {/* Timeline track */}
                        <div style={{ position: 'relative', flex: 1, height: TIMELINE_HEIGHT + 'px' }}>
                            {/* Hour grid lines */}
                            {hours.map(h => {
                                const top = ((h * 60 - TIMELINE_START) / TIMELINE_DURATION) * TIMELINE_HEIGHT;
                                return (
                                    <div key={'hline-' + h} style={{ position: 'absolute', top: top + 'px', left: 0, right: 0, height: '1px', background: h % 3 === 0 ? '#cbd5e0' : '#edf2f7', zIndex: 1 }} />
                                );
                            })}

                            {/* Log blocks */}
                            {timeLogs.map((log, index) => {
                                const startMin = parseInt(log.startTime.substring(0, 2)) * 60 + parseInt(log.startTime.substring(2));
                                const endMin = parseInt(log.endTime.substring(0, 2)) * 60 + parseInt(log.endTime.substring(2));
                                let adjustedEnd = endMin;
                                if (endMin <= startMin) {
                                    // Crosses midnight — show only the portion on this day
                                    adjustedEnd = TIMELINE_END;
                                }
                                const clampedStart = Math.max(startMin, TIMELINE_START);
                                const clampedEnd = Math.min(adjustedEnd, TIMELINE_END);
                                if (clampedEnd <= clampedStart) return null;
                                const top = ((clampedStart - TIMELINE_START) / TIMELINE_DURATION) * TIMELINE_HEIGHT;
                                const height = ((clampedEnd - clampedStart) / TIMELINE_DURATION) * TIMELINE_HEIGHT;
                                const color = this.getLogColor(log);
                                return (
                                    <div key={'vblock-' + log.id} style={{
                                        position: 'absolute',
                                        top: top + 'px',
                                        left: '8px',
                                        right: '8px',
                                        height: Math.max(height, 20) + 'px',
                                        background: color.bg,
                                        borderLeft: '4px solid ' + color.border,
                                        borderRadius: '6px',
                                        zIndex: 2,
                                        cursor: 'pointer',
                                        padding: '6px 10px 6px 10px',
                                        overflow: 'hidden',
                                        display: 'flex',
                                        flexDirection: 'column',
                                        justifyContent: height > 40 ? 'flex-start' : 'center',
                                        transition: 'box-shadow 0.2s, transform 0.15s',
                                        boxShadow: '0 1px 4px rgba(0,0,0,0.06)',
                                    }} onClick={() => this.openEditForm(log)} title={`${formatMilitaryTime(log.startTime)} – ${formatMilitaryTime(log.endTime)} | ${this.getSubProgramName(log.subProgramId)}`}>
                                        {/* Time + Title + Sub-program + Person — all in 1 line */}
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flexWrap: 'nowrap', overflow: 'hidden' }}>
                                            <span style={{ fontFamily: 'monospace', fontWeight: '700', fontSize: '0.78em', color: color.text, flexShrink: 0 }}>
                                                {formatMilitaryTime(log.startTime)} – {formatMilitaryTime(log.endTime)}
                                            </span>
                                            <span style={{ fontSize: '0.7em', fontWeight: '700', color: color.text, background: color.bg, border: '1px solid ' + color.border, padding: '1px 6px', borderRadius: '4px', flexShrink: 0 }}>
                                                {computeDuration(log.startTime, log.endTime)}
                                            </span>
                                            {log.title && (
                                                <>
                                                    <span style={{ color: '#a0aec0', fontSize: '0.78em', flexShrink: 0 }}>|</span>
                                                    <span style={{ fontSize: '0.8em', fontWeight: '600', color: '#2d3748', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                                        {log.title}
                                                    </span>
                                                </>
                                            )}
                                            <span style={{ color: '#a0aec0', fontSize: '0.78em', flexShrink: 0 }}>·</span>
                                            <span style={{ fontSize: '0.75em', color: '#718096', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                                {this.getSubProgramName(log.subProgramId)}
                                            </span>
                                            {log.personId && (
                                                <span style={{ fontSize: '0.75em', color: '#718096', whiteSpace: 'nowrap', flexShrink: 0 }}>· 👤 {this.getPersonName(log.personId)}</span>
                                            )}
                                            {/* Actions inline */}
                                            <span style={{ marginLeft: 'auto', display: 'flex', gap: '4px', flexShrink: 0 }} onClick={(e) => e.stopPropagation()}>
                                                <CButton color="info" size="sm" onClick={() => this.openEditForm(log)} style={{ borderRadius: '6px', padding: '2px 6px', fontSize: '0.7em' }}>✏️</CButton>
                                                <CButton color="danger" size="sm" onClick={() => this.handleDelete(log.id)} style={{ borderRadius: '6px', padding: '2px 6px', fontSize: '0.7em' }}>🗑️</CButton>
                                            </span>
                                        </div>
                                        {/* Notes */}
                                        {height > 75 && log.notes && (
                                            <div style={{ marginTop: '4px' }} onClick={(e) => e.stopPropagation()}>
                                                <CButton color="light" size="sm" onClick={() => this.toggleNotes(log.id)} style={{ padding: '1px 6px', fontSize: '0.65em', borderRadius: '4px', fontWeight: '600', border: '1px solid #e2e8f0' }}>
                                                    {this.state.expandedNotes[log.id] ? '🙈 Hide' : '📝 Notes'}
                                                </CButton>
                                                {this.state.expandedNotes[log.id] && (
                                                    <div style={{ marginTop: '4px', whiteSpace: 'pre-line', fontSize: '0.72em', color: '#4a5568', background: 'rgba(255,255,255,0.7)', padding: '4px 8px', borderRadius: '4px', border: '1px solid #e2e8f0' }}>{log.notes}</div>
                                                )}
                                            </div>
                                        )}
                                    </div>
                                );
                            })}

                            {/* Overlapping log blocks from adjacent days */}
                            {[...prevDayOverlapping, ...nextDayOverlapping].map((log) => {
                                const visStartMin = parseInt(log._visibleStartTime.substring(0, 2)) * 60 + parseInt(log._visibleStartTime.substring(2));
                                const visEndMin = parseInt(log._visibleEndTime.substring(0, 2)) * 60 + parseInt(log._visibleEndTime.substring(2));
                                const clampedStart = Math.max(visStartMin, TIMELINE_START);
                                const clampedEnd = Math.min(visEndMin, TIMELINE_END);
                                if (clampedEnd <= clampedStart) return null;
                                const top = ((clampedStart - TIMELINE_START) / TIMELINE_DURATION) * TIMELINE_HEIGHT;
                                const height = ((clampedEnd - clampedStart) / TIMELINE_DURATION) * TIMELINE_HEIGHT;
                                const color = this.getLogColor(log);
                                const isPrev = log._overlapType === 'prev';
                                return (
                                    <div key={'vblock-overlap-' + log._overlapType + '-' + log.id} style={{
                                        position: 'absolute',
                                        top: top + 'px',
                                        left: '8px',
                                        right: '8px',
                                        height: Math.max(height, 20) + 'px',
                                        background: `repeating-linear-gradient(135deg, ${color.bg}, ${color.bg} 4px, rgba(255,255,255,0.4) 4px, rgba(255,255,255,0.4) 8px)`,
                                        borderLeft: '4px dashed ' + color.border,
                                        borderRadius: '6px',
                                        zIndex: 2,
                                        cursor: 'default',
                                        padding: '6px 10px 6px 10px',
                                        overflow: 'hidden',
                                        display: 'flex',
                                        flexDirection: 'column',
                                        justifyContent: height > 40 ? 'flex-start' : 'center',
                                        opacity: 0.7,
                                        boxShadow: '0 1px 4px rgba(0,0,0,0.04)',
                                    }} title={`${log._label} ${formatMilitaryTime(log.startTime)} – ${formatMilitaryTime(log.endTime)} | ${this.getSubProgramName(log.subProgramId)}`}>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flexWrap: 'nowrap', overflow: 'hidden' }}>
                                            <span style={{ fontSize: '0.7em', fontWeight: '700', color: 'white', background: isPrev ? '#a0aec0' : '#718096', padding: '1px 8px', borderRadius: '4px', flexShrink: 0 }}>
                                                {isPrev ? '⬆️ prev day' : '⬇️ next day'}
                                            </span>
                                            <span style={{ fontFamily: 'monospace', fontWeight: '700', fontSize: '0.78em', color: color.text, flexShrink: 0 }}>
                                                {formatMilitaryTime(log._visibleStartTime)} – {formatMilitaryTime(log._visibleEndTime)}
                                            </span>
                                            {log.title && (
                                                <>
                                                    <span style={{ color: '#a0aec0', fontSize: '0.78em', flexShrink: 0 }}>|</span>
                                                    <span style={{ fontSize: '0.8em', fontWeight: '600', color: '#2d3748', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                                        {log.title}
                                                    </span>
                                                </>
                                            )}
                                            <span style={{ color: '#a0aec0', fontSize: '0.78em', flexShrink: 0 }}>·</span>
                                            <span style={{ fontSize: '0.75em', color: '#718096', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                                {this.getSubProgramName(log.subProgramId)}
                                            </span>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                    </div>
                </div>
            </div>
        );
    }

    renderForm() {
        const { editingId, formTitle, formStartTime, formEndTime, formSubProgramId, formPersonId, formNotes, subPrograms, persons, formHighlight } = this.state;

        return (
            <div ref={this.formRef}>
            <CCard className="mb-4" style={{ border: 'none', borderRadius: '16px', boxShadow: formHighlight ? '0 0 0 4px rgba(102, 126, 234, 0.5), 0 10px 40px rgba(102, 126, 234, 0.25)' : '0 10px 40px rgba(102, 126, 234, 0.15)', overflow: 'hidden', transition: 'box-shadow 0.3s ease' }}>
                <div style={{ background: 'linear-gradient(135deg, #667eea, #764ba2)', padding: '16px 32px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <h5 style={{ color: 'white', margin: 0, fontWeight: '700' }}>{editingId ? '✏️ Edit Time Log' : '➕ New Time Log'}</h5>
                    <button
                        type="button"
                        onClick={this.closeForm}
                        title="Close"
                        aria-label="Close"
                        style={{ background: 'rgba(255, 255, 255, 0.2)', color: 'white', border: 'none', borderRadius: '8px', width: '32px', height: '32px', fontSize: '1.1em', lineHeight: 1, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
                    >
                        ✖
                    </button>
                </div>
                <CCardBody style={{ background: '#fafbff', padding: '28px 32px' }}>
                    <form onSubmit={this.handleFormSubmit}>
                        <CRow>
                            <CCol md="6">
                                <div style={{ marginBottom: '16px' }}>
                                    <label style={{ fontWeight: '600', color: '#4a5568', fontSize: '0.9em', marginBottom: '6px', display: 'block' }}>Sub-Program <span style={{ color: '#e53e3e' }}>*</span></label>
                                    <Select
                                        value={subPrograms.map(sp => ({ value: String(sp.id), label: this.getSubProgramDisplay(sp) })).find(o => o.value === formSubProgramId) || null}
                                        onChange={(choice) => this.setState({ formSubProgramId: choice ? choice.value : '' })}
                                        options={subPrograms.map(sp => ({ value: String(sp.id), label: this.getSubProgramDisplay(sp) }))}
                                        isClearable={true}
                                        placeholder="Search sub-program..."
                                        styles={{ control: (base) => ({ ...base, borderRadius: '10px', border: '2px solid #e8ecff', minHeight: '42px' }) }}
                                    />
                                </div>
                            </CCol>
                            <CCol md="6">
                                <div style={{ marginBottom: '16px' }}>
                                    <label style={{ fontWeight: '600', color: '#4a5568', fontSize: '0.9em', marginBottom: '6px', display: 'block' }}>Title</label>
                                    <CInput
                                        value={formTitle}
                                        onChange={(e) => this.setState({ formTitle: e.target.value })}
                                        placeholder="e.g. standup call"
                                        style={{ borderRadius: '10px', border: '2px solid #e8ecff', padding: '10px 14px' }}
                                    />
                                </div>
                            </CCol>
                        </CRow>
                        <CRow>
                            <CCol md="3">
                                <div style={{ marginBottom: '16px' }}>
                                    <label style={{ fontWeight: '600', color: '#4a5568', fontSize: '0.9em', marginBottom: '6px', display: 'block' }}>Start Time <span style={{ color: '#e53e3e' }}>*</span></label>
                                    <div style={{ display: 'flex', gap: '6px', alignItems: 'center' }}>
                                        <CInput
                                            value={formStartTime}
                                            onChange={(e) => this.setState({ formStartTime: e.target.value })}
                                            placeholder="0900"
                                            maxLength="4"
                                            pattern="[0-2][0-9][0-5][0-9]"
                                            required
                                            style={{ borderRadius: '10px', border: '2px solid #e8ecff', padding: '10px 14px', fontFamily: 'monospace', fontSize: '1.1em', fontWeight: '700', textAlign: 'center', flex: 1 }}
                                        />
                                        <button
                                            type="button"
                                            onClick={() => { const now = new Date(); this.setState({ formStartTime: String(now.getHours()).padStart(2, '0') + String(now.getMinutes()).padStart(2, '0') }); }}
                                            title="Set to current time"
                                            style={{ padding: '8px 10px', borderRadius: '8px', border: '2px solid #e8ecff', background: 'white', cursor: 'pointer', fontWeight: '600', fontSize: '0.8em', color: '#667eea', whiteSpace: 'nowrap', transition: 'all 0.2s' }}
                                        >🕐 Now</button>
                                        {formStartTime && <button
                                            type="button"
                                            onClick={() => this.setState({ formStartTime: '' })}
                                            title="Clear"
                                            style={{ padding: '8px 8px', borderRadius: '8px', border: 'none', background: 'transparent', cursor: 'pointer', fontSize: '0.85em', color: '#a0aec0', transition: 'color 0.2s', lineHeight: 1 }}
                                        >✕</button>}
                                    </div>
                                </div>
                            </CCol>
                            <CCol md="3">
                                <div style={{ marginBottom: '16px' }}>
                                    <label style={{ fontWeight: '600', color: '#4a5568', fontSize: '0.9em', marginBottom: '6px', display: 'block' }}>End Time <span style={{ color: '#a0aec0', fontWeight: '400' }}>(optional)</span></label>
                                    <div style={{ display: 'flex', gap: '6px', alignItems: 'center' }}>
                                        <CInput
                                            value={formEndTime}
                                            onChange={(e) => this.setState({ formEndTime: e.target.value })}
                                            placeholder="1030"
                                            maxLength="4"
                                            pattern="[0-2][0-9][0-5][0-9]"
                                            style={{ borderRadius: '10px', border: '2px solid #e8ecff', padding: '10px 14px', fontFamily: 'monospace', fontSize: '1.1em', fontWeight: '700', textAlign: 'center', flex: 1 }}
                                        />
                                        <button
                                            type="button"
                                            onClick={() => { const now = new Date(); this.setState({ formEndTime: String(now.getHours()).padStart(2, '0') + String(now.getMinutes()).padStart(2, '0') }); }}
                                            title="Set to current time"
                                            style={{ padding: '8px 10px', borderRadius: '8px', border: '2px solid #e8ecff', background: 'white', cursor: 'pointer', fontWeight: '600', fontSize: '0.8em', color: '#667eea', whiteSpace: 'nowrap', transition: 'all 0.2s' }}
                                        >🕐 Now</button>
                                        {formEndTime && <button
                                            type="button"
                                            onClick={() => this.setState({ formEndTime: '' })}
                                            title="Clear"
                                            style={{ padding: '8px 8px', borderRadius: '8px', border: 'none', background: 'transparent', cursor: 'pointer', fontSize: '0.85em', color: '#a0aec0', transition: 'color 0.2s', lineHeight: 1 }}
                                        >✕</button>}
                                    </div>
                                </div>
                            </CCol>
                            <CCol md="3">
                                <div style={{ marginBottom: '16px' }}>
                                    <label style={{ fontWeight: '600', color: '#4a5568', fontSize: '0.9em', marginBottom: '6px', display: 'block' }}>Person</label>
                                    <Select
                                        value={persons.map(p => ({ value: String(p.id), label: p.name })).find(o => o.value === formPersonId) || null}
                                        onChange={(choice) => this.setState({ formPersonId: choice ? choice.value : '' })}
                                        options={persons.map(p => ({ value: String(p.id), label: p.name }))}
                                        isClearable={true}
                                        placeholder="Search person..."
                                        styles={{ control: (base) => ({ ...base, borderRadius: '10px', border: '2px solid #e8ecff', minHeight: '42px' }) }}
                                    />
                                </div>
                            </CCol>
                            <CCol md="6">
                                <div style={{ marginBottom: '16px' }}>
                                    <label style={{ fontWeight: '600', color: '#4a5568', fontSize: '0.9em', marginBottom: '6px', display: 'block' }}>Notes</label>
                                    <textarea
                                        value={formNotes}
                                        onChange={(e) => this.setState({ formNotes: e.target.value })}
                                        placeholder="Optional notes..."
                                        rows="4"
                                        style={{ display: 'block', width: '100%', padding: '10px 14px', border: '2px solid #e8ecff', borderRadius: '10px', resize: 'vertical', fontSize: '0.95em' }}
                                    />
                                </div>
                            </CCol>
                        </CRow>
                        <div style={{ display: 'flex', gap: '12px', marginTop: '8px' }}>
                            <CButton type="submit" style={{ borderRadius: '10px', fontWeight: '700', padding: '10px 24px', background: 'linear-gradient(135deg, #48bb78, #38a169)', border: 'none', color: 'white', boxShadow: '0 4px 15px rgba(72, 187, 120, 0.4)' }}>{editingId ? '💾 Update' : '✅ Create'}</CButton>
                            <CButton onClick={this.closeForm} style={{ borderRadius: '10px', fontWeight: '600', padding: '10px 24px', background: '#edf2f7', border: 'none', color: '#4a5568' }}>Cancel</CButton>
                        </div>
                    </form>
                </CCardBody>
            </CCard>
            </div>
        );
    }
}

export default TimeLogs;
